// Regeneration on touch over the public corpus (M2-10 part 3, DEC-011): in every AC1032 DXF
// file, each linear and aligned dimension that draws a stored `*D` block has its second
// extension origin stretched, is regenerated by the dimension engine (`regenerateDimension`)
// and its block rewritten (`writeDimensionBlock`), as STRETCH does in the app. The save must
// then reopen with the dimension where it was stretched to, its block holding what the engine
// draws for it (the health check passes on the reopened file) and every other object exactly
// as read: `structuralDiff` ignoring the dimensions, their blocks' records and contents (old
// and new) and a DEFPOINTS layer the regeneration made reports nothing. Save is AC1032 DXF
// only (DEC-047), so older files and DWGs are not saved here.
import { readFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { dimensionHealth, regenerateDimension } from '@triya/dims';
import {
  ChangeSetBuilder,
  DocumentModel,
  stretchGeometry,
  writeDimensionBlock,
  type Color,
  type DimensionGeometry,
  type Entity,
} from '@triya/engine';
import { aciOfTrueColor, documentInit, exportDocument, readCadDocument } from '@triya/io';
import { textMeasure } from '@triya/render';
import { describe, expect, it } from 'vitest';
import { loadManifest, readableFiles } from '../corpus/manifest.ts';
import { bundledFontBook } from '../render/bundled-fonts.ts';
import { withPinnedClock } from '../roundtrip/clock.ts';
import { structuralDiff } from '../roundtrip/diff.ts';

const corpusDir = fileURLToPath(new URL('../../../../corpus/', import.meta.url));
const manifest = loadManifest(`${corpusDir}corpus.json`);
const files = readableFiles(manifest).filter(
  (f) => f.version === 'AC1032' && f.format === 'dxf-ascii',
);
const D = { x: 7, y: 0 };
const PER_FILE_BUDGET_MS = 20_000;

/** As the health gate: a DXF DIMSTYLE's ACI stands for its block's true colour. */
const colors = (g: Color, s: Color): boolean =>
  g.kind === 'aci' && s.kind === 'rgb' && aciOfTrueColor(s.r, s.g, s.b) === g.index;

type Linear = Extract<DimensionGeometry, { dimType: 'linear' | 'aligned' }>;
const isLinear = (e: Entity): e is Entity & { geom: Linear } =>
  e.geom.kind === 'DIMENSION' && (e.geom.dimType === 'linear' || e.geom.dimType === 'aligned');

const regenerated: string[] = [];

describe('dimension regeneration on touch over the public corpus (M2-10 part 3)', () => {
  it.each(files.map((f) => [f.path, f] as const))(
    'stretches, regenerates and saves the linear dimensions of %s',
    (_path, f) => {
      const bytes = new Uint8Array(readFileSync(`${corpusDir}${f.path}`));
      withPinnedClock(() => {
        const original = readCadDocument(bytes);
        const model = DocumentModel.create(documentInit(readCadDocument(bytes)));
        const fonts = bundledFontBook();
        const measure = textMeasure({ fonts, style: (h) => model.tables.textStyles.get(h) });
        const dims = [...model.entities()].filter(
          (e) =>
            isLinear(e) &&
            e.geom.block !== undefined &&
            model.blocks.has(e.geom.block) &&
            dimensionHealth(e, model, measure, colors)?.ok,
        );
        if (dims.length === 0) return;
        const layersBefore = new Set(model.tables.layers.keys());
        const ignore = new Set<number>();
        const touch = (h: string) => ignore.add(Number.parseInt(h, 16));
        const b = new ChangeSetBuilder(model);
        for (const e of dims) {
          const g = e.geom as Linear;
          const at = g.second;
          const r = stretchGeometry(g, (p) => p.x === at.x && p.y === at.y, D, {
            dimensions: true,
          });
          expect(r.kind, `${f.path} ${e.handle}`).toBe('shape');
          if (r.kind !== 'shape') continue;
          b.updateEntity(e.id, { geom: r.geom });
          const drawn = regenerateDimension({ ...e, geom: r.geom }, model, measure);
          expect(drawn, `${f.path} ${e.handle}`).toBeDefined();
          touch(e.handle);
          touch(g.block!);
          for (const id of model.blockEntities(g.block!)) touch(model.entity(id)!.handle);
          writeDimensionBlock(b, model, e.id, drawn!);
        }
        model.apply(b.build());
        for (const e of dims) {
          for (const id of model.blockEntities((e.geom as Linear).block!)) {
            touch(model.entity(id)!.handle);
          }
        }
        for (const h of model.tables.layers.keys()) if (!layersBefore.has(h)) touch(h);

        const saved = exportDocument(readCadDocument(bytes), model, { format: 'dxf' });
        const reopened = DocumentModel.create(documentInit(readCadDocument(saved)));
        const again = textMeasure({ fonts, style: (h) => reopened.tables.textStyles.get(h) });
        for (const e of dims) {
          const back = reopened.entityByHandle(e.handle)!;
          const before = e.geom as Linear;
          expect((back.geom as Linear).second, `${f.path} ${e.handle}`).toEqual({
            x: before.second.x + D.x,
            y: before.second.y + D.y,
          });
          const health = dimensionHealth(back, reopened, again, colors);
          expect(health?.problems ?? ['no health'], `${f.path} ${e.handle}`).toEqual([]);
          regenerated.push(`${f.path} ${e.handle}`);
        }
        // Everything else as read. The new handles move $HANDSEED; the layer table and the
        // block records' table list a new DEFPOINTS layer and nothing else.
        const diff = structuralDiff(original, readCadDocument(saved), {
          ignoreHandles: ignore,
        }).differences.filter((d) => !(d.handle === '0' && /HANDSEED/i.test(d.path)));
        expect(diff.slice(0, 5), f.path).toEqual([]);
      });
    },
    PER_FILE_BUDGET_MS,
  );

  it('regenerated dimensions on the corpus', () => {
    // Filled in by the cases above (vitest runs a file's tests in order).
    // Nine dimensions in two files (the AC1032 acadsharp sample and ezdxf's uncommon.dxf);
    // adding an AC1032 corpus file with linear dimensions raises it.
    expect(regenerated).toHaveLength(9);
    expect(new Set(regenerated.map((r) => r.split(' ')[0])).size).toBe(2);
  });
});
